        amountGrossCurrency: 13500,
      },
      {
        row: 2,
        date: "2026-02-22",
        description: "Kontorstoler",
        account: { id: acct1920.id },
        amount: -13500,
        amountCurrency: -13500,
        amountGross: -13500,
        amountGrossCurrency: -13500,
      },
    ],
  };
  const voucherResC = await api("POST", "/ledger/voucher", voucherPayloadC);
  if (voucherResC.status < 300) {
